// AUTO-GENERATED by workflow — art. Do not hand-edit; re-run integrate.mjs.
// ENHANCED EDITION (art_v2): consumable item icons re-drawn "juicy". Every icon
// commits to a top-left light source with 3–4 tonal steps per material, a glass
// specular streak on flasks, soft radial glow on liquids/gems, kira sparkles and
// rim light for that anime pop. Names / sizes / anchors / imports are UNCHANGED —
// strict drop-in replacement. New private helpers are additive only.
import { defineSprite, defineAnim, Painter } from '../../engine/sprites.js';
import { P, lighten, darken, mix, withAlpha, tint } from '../../engine/palette.js';
